36	/// Handler for the "check" command of the Biome CLI
37	pub(crate) fn check(
38	    session: CliSession,
39	    payload: CheckCommandPayload,
40	) -> Result<(), CliDiagnostic> {
41	    let CheckCommandPayload {
42	        apply,
43	        apply_unsafe,
44	        cli_options,
45	        configuration,
46	        mut paths,
47	        stdin_file_path,
48	        linter_enabled,
49	        organize_imports_enabled,
50	        formatter_enabled,
51	        since,
52	        staged,
53	        changed,
54	    } = payload;
55	    setup_cli_subscriber(cli_options.log_level, cli_options.log_kind);
56	
57	    let fix_file_mode = if apply && apply_unsafe {
58	        return Err(CliDiagnostic::incompatible_arguments(
59	            "--apply",
60	            "--apply-unsafe",
61	        ));
62	    } else if !apply && !apply_unsafe {
63	        None
64	    } else if apply && !apply_unsafe {
65	        Some(FixFileMode::SafeFixes)
66	    } else {
67	        Some(FixFileMode::SafeAndUnsafeFixes)
68	    };
69	
70	    let loaded_configuration =
71	        load_configuration(&session.app.fs, cli_options.as_configuration_path_hint())?;
72	    validate_configuration_diagnostics(
73	        &loaded_configuration,
74	        session.app.console,
75	        cli_options.verbose,
76	    )?;
77	    resolve_manifest(&session)?;
78	
79	    let LoadedConfiguration {
80	        configuration: mut fs_configuration,
81	        directory_path: configuration_path,
82	        ..
83	    } = loaded_configuration;
84	
85	    let formatter = fs_configuration
86	        .formatter
87	        .get_or_insert_with(PartialFormatterConfiguration::default);
88	
89	    if formatter_enabled.is_some() {
90	        formatter.enabled = formatter_enabled;
91	    }
92	
93	    let linter = fs_configuration
94	        .linter
95	        .get_or_insert_with(PartialLinterConfiguration::default);
96	
97	    if linter_enabled.is_some() {
98	        linter.enabled = linter_enabled;
99	    }
100	
101	    let organize_imports = fs_configuration
102	        .organize_imports
103	        .get_or_insert_with(PartialOrganizeImports::default);
104	
105	    if organize_imports_enabled.is_some() {
106	        organize_imports.enabled = organize_imports_enabled;
107	    }
108	
109	    if let Some(mut configuration) = configuration {
110	        if let Some(linter) = configuration.linter.as_mut() {
111	            // Don't overwrite rules from the CLI configuration.
112	            // Otherwise, rules that are disabled in the config file might
113	            // become re-enabled due to the defaults included in the CLI
114	            // configuration.
115	            linter.rules = None;
116	        }
117	        fs_configuration.merge_with(configuration);
118	    }
119	
120	    // check if support of git ignore files is enabled
121	    let vcs_base_path = configuration_path.or(session.app.fs.working_directory());
122	    let (vcs_base_path, gitignore_matches) =
123	        fs_configuration.retrieve_gitignore_matches(&session.app.fs, vcs_base_path.as_deref())?;
124	
125	    let stdin = get_stdin(stdin_file_path, &mut *session.app.console, "check")?;
126	
127	    if let Some(_paths) =
128	        get_files_to_process(since, changed, staged, &session.app.fs, &fs_configuration)?
129	    {
130	        paths = _paths;
131	    }
132	
133	    session
134	        .app
135	        .workspace
136	        .register_project_folder(RegisterProjectFolderParams {
137	            path: session.app.fs.working_directory(),
138	            set_as_current_workspace: true,
139	        })?;
140	
141	    session
142	        .app
143	        .workspace
144	        .update_settings(UpdateSettingsParams {
145	            workspace_directory: session.app.fs.working_directory(),
146	            configuration: fs_configuration,
147	            vcs_base_path,
148	            gitignore_matches,
149	        })?;
150	
151	    execute_mode(
152	        Execution::new(TraversalMode::Check {
153	            fix_file_mode,
154	            stdin,
155	        })
156	        .set_report(&cli_options),
157	        session,
158	        &cli_options,
159	        paths,
160	    )
161	}
