17	pub(crate) fn lint_with_guard<'ctx>(
18	    ctx: &'ctx SharedTraversalOptions<'ctx, '_>,
19	    workspace_file: &mut WorkspaceFile,
20	) -> FileResult {
21	    tracing::info_span!("Processes linting", path =? workspace_file.path.display()).in_scope(
22	        move || {
23	            let mut input = workspace_file.input()?;
24	            let mut changed = false;
25	            if let Some(fix_mode) = ctx.execution.as_fix_file_mode() {
26	                let fix_result = workspace_file
27	                    .guard()
28	                    .fix_file(*fix_mode, false)
29	                    .with_file_path_and_code(
30	                        workspace_file.path.display().to_string(),
31	                        category!("lint"),
32	                    )?;
33	
34	                ctx.push_message(Message::SkippedFixes {
35	                    skipped_suggested_fixes: fix_result.skipped_suggested_fixes,
36	                });
37	
38	                let mut output = fix_result.code;
39	
40	                match workspace_file.as_extension() {
41	                    Some("astro") => {
42	                        output = AstroFileHandler::output(input.as_str(), output.as_str());
43	                    }
44	                    Some("vue") => {
45	                        output = VueFileHandler::output(input.as_str(), output.as_str());
46	                    }
47	                    Some("svelte") => {
48	                        output = SvelteFileHandler::output(input.as_str(), output.as_str());
49	                    }
50	                    _ => {}
51	                }
52	                if output != input {
53	                    changed = true;
54	                    workspace_file.update_file(output)?;
55	                    input = workspace_file.input()?;
56	                }
57	            }
58	
59	            let max_diagnostics = ctx.remaining_diagnostics.load(Ordering::Relaxed);
60	            let rule = if let TraversalMode::Lint { rule, .. } = ctx.execution.traversal_mode() {
61	                *rule
62	            } else {
63	                None
64	            };
65	            let pull_diagnostics_result = workspace_file
66	                .guard()
67	                .pull_diagnostics(
68	                    RuleCategories::LINT | RuleCategories::SYNTAX,
69	                    max_diagnostics.into(),
70	                    rule,
71	                )
72	                .with_file_path_and_code(
73	                    workspace_file.path.display().to_string(),
74	                    category!("lint"),
75	                )?;
76	
77	            let no_diagnostics = pull_diagnostics_result.diagnostics.is_empty()
78	                && pull_diagnostics_result.skipped_diagnostics == 0;
79	
80	            if !no_diagnostics {
81	                let input = match workspace_file.as_extension() {
82	                    Some("astro") => AstroFileHandler::input(input.as_str()).to_string(),
83	                    Some("vue") => VueFileHandler::input(input.as_str()).to_string(),
84	                    Some("svelte") => SvelteFileHandler::input(input.as_str()).to_string(),
85	                    _ => input,
86	                };
87	
88	                ctx.push_message(Message::Diagnostics {
89	                    name: workspace_file.path.display().to_string(),
90	                    content: input,
91	                    diagnostics: pull_diagnostics_result
92	                        .diagnostics
93	                        .into_iter()
94	                        .map(Error::from)
95	                        .collect(),
96	                    skipped_diagnostics: pull_diagnostics_result.skipped_diagnostics as u32,
97	                });
98	            }
99	
100	            if changed {
101	                Ok(FileStatus::Changed)
102	            } else {
103	                Ok(FileStatus::Unchanged)
104	            }
105	        },
106	    )
107	}
