///
/// This groups together the current flags (`--write`/`--fix`/`--unsafe`) as well
/// as the deprecated aliases (`--apply`/`--apply-unsafe`).
#[derive(Debug, Copy, Clone)]
pub(crate) struct FixFileModeOptions {
    apply: bool,
    apply_unsafe: bool,
    write: bool,
    fix: bool,
    unsafe_: bool,
}

/// Validates that the fix related arguments are not used together in an
/// incompatible way, returning an error otherwise.
pub(crate) fn check_fix_incompatible_arguments(
    options: FixFileModeOptions,
) -> Result<(), CliDiagnostic> {
    let FixFileModeOptions {
        apply,
        apply_unsafe,
        write,
        fix,
        ..
    } = options;
    if apply && apply_unsafe {
        return Err(CliDiagnostic::incompatible_arguments(
            "--apply",
            "--apply-unsafe",
        ));
    } else if (apply || apply_unsafe) && (write || fix) {
        return Err(CliDiagnostic::incompatible_arguments(
            if apply { "--apply" } else { "--apply-unsafe" },
            if write { "--write" } else { "--fix" },
        ));
    } else if write && fix {
        return Err(CliDiagnostic::incompatible_arguments("--write", "--fix"));
    }
    Ok(())
}

/// Computes the [FixFileMode] from the given [FixFileModeOptions].
///
/// - It returns an error if the given options are incompatible.
/// - It returns [None] if no fix is requested.
/// - It returns [Some] with the resolved [FixFileMode] otherwise.
pub(crate) fn determine_fix_file_mode(
    options: FixFileModeOptions,
) -> Result<Option<FixFileMode>, CliDiagnostic> {
    check_fix_incompatible_arguments(options)?;

    let FixFileModeOptions {
        apply,
        apply_unsafe,
        write,
        fix,
        unsafe_,
    } = options;

    let safe_fixes = apply || write || fix;
    let unsafe_fixes = apply_unsafe || ((write || fix) && unsafe_);

    if unsafe_fixes {
        Ok(Some(FixFileMode::SafeAndUnsafeFixes))
    } else if safe_fixes {
        Ok(Some(FixFileMode::SafeFixes))
    } else {
        Ok(None)
    }
}

