                determine_fix_file_mode(FixFileModeOptions {
                    apply,
                    apply_unsafe,
                    write,
                    fix,
                    unsafe_,
                })
                .unwrap(),
                Some(FixFileMode::SafeAndUnsafeFixes)
            );
        }
    }

    #[test]
    fn no_fix() {
        let (apply, apply_unsafe, write, fix, unsafe_) = (false, false, false, false, false);
        assert_eq!(
            determine_fix_file_mode(FixFileModeOptions {
                apply,
                apply_unsafe,
                write,
                fix,
                unsafe_,
            })
            .unwrap(),
            None
        );
    }
